      "claim": "4D + 7 = 43",
      "evidence": "Combine like terms in the equation from step 5.",
      "weight": 0.10,
      "depends_on": [5]
    },
    {
      "id": 7,
      "claim": "D = 9",
      "evidence": "Subtract 7 from both sides (43 − 7 = 36) and divide by 4 (36 ÷ 4 = 9).",
      "weight": 0.20,
      "depends_on": [6]
    },
    {
      "id": 8,
      "claim": "L = 16",
      "evidence": "Use L = D + 7 from step 2 with D = 9 from step 7: 9 + 7 = 16.",
